CREATE TABLE `recall` (
  `recall_uid` bigint NOT NULL,
  `recall_product_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recall_brand_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recall_model_name` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recall_model_cnt` int DEFAULT NULL,
  `barcode_num` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cert_num` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recall_type_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recall_means` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `recall_cmpny_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `maker_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `making_cntry_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `publish_date` char(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `harm_dscr` text COLLATE utf8mb4_unicode_ci,
  `accident_case_dscr` text COLLATE utf8mb4_unicode_ci,
  `publish_action_dscr` text COLLATE utf8mb4_unicode_ci,
  `synced_at` datetime DEFAULT NULL,
  `normalized_product_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `normalized_model_name` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `normalized_cert_num` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`recall_uid`),
  KEY `IX_RECALL_BARCODE` (`barcode_num`),
  KEY `IX_RECALL_CERT_NUM` (`cert_num`),
  KEY `IX_RECALL_PRODUCT_NAME` (`recall_product_name`),
  KEY `IX_RECALL_PUBLISH_DATE` (`publish_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
