INSERT INTO `recall` VALUES (10019346,'전기냉장*냉동기기(와인셀러)','HAIER','HWC200MNB, HWC120MNB',0,NULL,'SU07146-22001',NULL,'자발적리콜',NULL,'하이얼전자판매 주식회사',NULL,NULL,'20230724','- 제조년월 기준 2022년 6월 ~ 2023년 4월 생산월 제품의 온도 감지, 제어 기능 강화 등 성능과 기능을 개선하여 제품고장으로 인한 재산상의 손실 방지를 위한 자발적 리콜\r\n- 해당없음 (KC 전기 안전기준에 따라 인증취득)\n','접수된 위해 내용 없음','하이얼코리아 서비스(1588-6645)에 전화 후 무상수리 등록 및 조치 받을 것','2026-09-21 19:06:02','전기냉장냉동기기와인셀러','HWC200MNBHWC120MNB','SU0714622001'),(10019347,'자동차 타이어','BFGoodrich','205/60R16 92H TL  ADVANTAGE TOURING GO ',0,NULL,'B132R489-21001',NULL,'자발적리콜',NULL,'미쉐린코리아(주)',NULL,NULL,'20230712','일부 타이어에서 벨트가 균일하지 않은 간격으로(off-set belt) 제조되었을 수 있음을 확인함\n','제품 제원과의 편차가 발생하며 휠밸런싱의 불균형으로 인해 소비자가 진동을 느낄 수 있고, 주행 중에 갑작스러운 공기압 손실 또한 완전히 배제할 수 없음','해당 제품을 보유 중인 판매처는 즉시 판매를 중지할 것\r\n해당 제품을 사용 중이 소비자는 판매처에 문의 후 새 제품(대체품)으로 교환 조치 받을 것','2026-09-21 19:06:00','자동차타이어','20560R1692HTLADVANTAGETOURINGGO','B132R48921001'),(10019348,'폴리우레탄 폼','피셔','#700068 PUP 750 K B3',0,NULL,'해당없슴',NULL,'자발적리콜',NULL,'피셔코리아주식회사',NULL,NULL,'20230714','제품 용기 터짐 가능\n','용기와의 충돌로 사용자 위해 가능','해당 제품을 보유하고 있는 소비자는 즉시 사용 중지 바람.\r\n판매/제조사 직원의 리콜 전화를 받아 제품 리콜에 협조 바람.\r\n문의처/영업담당에게 연락하여 차후 대응에 대해 문의 바람.','2026-09-21 19:06:00','폴리우레탄폼','700068PUP750KB3','해당없슴'),(10019350,'앰프 내장형 스피커','BOSE','Acoustimass 6 III 홈 엔터테인먼트 시스템 Acoustimass 10 III 홈 엔터테인먼트 시스템 Acoustimass 15 II 홈 엔터테인먼트 시스템 Acoustimass15 홈 시어터 스피커 시스템 Lifestyle 5 시리즈 II 파워드 스피커 시스템 라이프스타일 12 파워드 스피커 시스템 라이프스타일 20 파워드 스피커 시스템 Lifestyle 30 파워드 스피커 시스템 Lifestyle 50 파워드 스피커 시스템 Powered Acoustimass 5 시리즈 III 스피커 시스템 Powered Acoustimass 25 시리즈 II 스피커 시스템 Powered Acoustimass 30 시리즈 II 스피커 시스템',0,NULL,'SV09010-3002A / SV09010-3001C / SV09010-2003C / SV09010-2003 / SV09010-1002 / SV09010-1001 / SV09010-1001A',NULL,'자발적리콜',NULL,'(주)세기에이치이',NULL,NULL,'20230724','2006년 4월이전 제조된 일부 Powered Acoustimass (앰프내장형스피커) 일부 제품의 화재 발생 가능성 (현재 국내에서 발생한 상황없음)\n','2006년 4월이전 제조된 일부 Powered Acoustimass (앰프내장형스피커) 일부 제품의 화재 발생 가능성  (현재 국내에서 발생한 상황없음)','현재 제품을 사용중이라면 Bass 전원을 빼고 자사 리콜 프로그램에 문의하여